import{_ as e,o as s,c as o,a3 as t}from"./chunks/framework.qCVWde4n.js";const u=JSON.parse('{"title":"Mod 分享码","description":"","frontmatter":{},"headers":[],"relativePath":"features/sharecode.md","filePath":"features/sharecode.md","lastUpdated":1791133906000}'),l={name:"features/sharecode.md"};function n(r,a,i,d,c,p){return s(),o("div",null,[...a[0]||(a[0]=[t(`<h1 id="mod-分享码" tabindex="-1">Mod 分享码 <a class="header-anchor" href="#mod-分享码" aria-label="Permalink to &quot;Mod 分享码&quot;">​</a></h1><p>分享码是框架分发 Mod 的核心机制：<strong>把 mod.json 变成一段文本</strong>，能从任何聊天软件直接粘贴。</p><h2 id="它长什么样" tabindex="-1">它长什么样 <a class="header-anchor" href="#它长什么样" aria-label="Permalink to &quot;它长什么样&quot;">​</a></h2><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>AFMOD1:ew0KICAibW9kTmFtZSI6ICLnpLrkvovCt+a1i+ivlSIsDQog...</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><ul><li>开头固定是 <code>AFMOD1:</code>（这是版本标记，方便以后升级格式）</li><li>后面是一长串 Base64 字符</li></ul><h2 id="它是怎么做出来的" tabindex="-1">它是怎么做出来的 <a class="header-anchor" href="#它是怎么做出来的" aria-label="Permalink to &quot;它是怎么做出来的&quot;">​</a></h2><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>mod.json 文本</span></span>
<span class="line"><span>      ↓ UTF-8 编码</span></span>
<span class="line"><span>      ↓ Base64 编码</span></span>
<span class="line"><span>      ↓ 前面加 &quot;AFMOD1:&quot;</span></span>
<span class="line"><span>分享码</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br></div></div><div class="tip custom-block"><p class="custom-block-title">为什么选 Base64 而不是压缩</p><p>目标环境是 .NET 3.5 / Unity Mono，<strong>压缩库不一定可用</strong>，而 Base64 是 <code>mscorlib</code> 里绝对有的。</p><p>mod.json 本身只有几 KB，Base64 只增大约 33% 体积，换来的是<strong>零依赖、跨设备稳定</strong>。这笔交易很划算。</p></div><h2 id="两种用法" tabindex="-1">两种用法 <a class="header-anchor" href="#两种用法" aria-label="Permalink to &quot;两种用法&quot;">​</a></h2><h3 id="用分享码-推荐" tabindex="-1">用分享码（推荐） <a class="header-anchor" href="#用分享码-推荐" aria-label="Permalink to &quot;用分享码（推荐）&quot;">​</a></h3><p><strong>给别人：</strong></p><ol><li>面板 → 「Mod」页 → 找到那个 Mod → 点「分享」</li><li>分享码自动复制到剪贴板</li><li>粘贴到任意聊天窗口发出去</li></ol><p><strong>自己导入：</strong></p><ol><li>面板 → 「参数」页 → 「粘贴导入分享码」</li><li>粘贴 → 确认</li><li><strong>完全退出游戏，重新启动</strong></li></ol><h3 id="用文件-备选" tabindex="-1">用文件（备选） <a class="header-anchor" href="#用文件-备选" aria-label="Permalink to &quot;用文件（备选）&quot;">​</a></h3><p>如果分享码被聊天软件截断了，可以让对方<strong>存成 <code>.txt</code> 文件</strong>发过来：</p><p>把那个 <code>.txt</code> 丢进 <code>mods/_sharein/</code> 目录，<strong>下次进游戏会自动「物化」</strong> 成 <code>mods/&lt;名字&gt;/mod.json</code> 并加载。</p><div class="tip custom-block"><p class="custom-block-title"><code>_sharein/</code> 是自动导入的收件箱</p><p>框架启动时会扫描 <code>mods/_sharein/</code> 下的 <code>.txt</code> 文件，把里面的分享码解码成正常的 Mod 目录。</p><p>所以手动导入的流程是：<strong>丢文件 → 重开游戏 → 自动装好</strong>。</p></div><h2 id="分享码里有什么" tabindex="-1">分享码里有什么 <a class="header-anchor" href="#分享码里有什么" aria-label="Permalink to &quot;分享码里有什么&quot;">​</a></h2><p>分享码<strong>就是完整的 <code>mod.json</code> 内容</strong>，所以它能携带：</p><ul><li>参数改动</li><li>自定义舰船</li><li>自定义编队</li><li>元信息（名字、作者、版本）</li></ul><div class="warning custom-block"><p class="custom-block-title">分享码不含模型文件</p><p><code>.unity3d</code> 模型包<strong>不包含在分享码里</strong>（它是二进制文件，编进 Base64 会非常长）。</p><p>所以如果你的 Mod 用了自制模型，别人导入分享码后<strong>只会回退到内置模型</strong>。想完整分享，得另外把模型包发过去。</p></div><h2 id="安全的解析方式" tabindex="-1">安全的解析方式 <a class="header-anchor" href="#安全的解析方式" aria-label="Permalink to &quot;安全的解析方式&quot;">​</a></h2><p>分享码解码失败时，框架的处理是：<strong>只记日志，返回空，绝不抛异常</strong>。</p><p>所以：</p><ul><li>粘贴了一个坏掉的码 → 游戏不会崩，只是导入失败</li><li>日志页会记录失败原因</li></ul><div class="tip custom-block"><p class="custom-block-title">想先看看别人给的码里是什么</p><p>不用直接导入。去 <a href="https://atlanticfleet.asia/mods/" target="_blank" rel="noreferrer">Mod 仓库</a> 的<strong>分享码解析器</strong>：</p><p>把码粘贴到网页上，它会告诉你这是什么 Mod、作者是谁、改了哪些参数。确认没问题再导入。</p></div><h2 id="常见问题" tabindex="-1">常见问题 <a class="header-anchor" href="#常见问题" aria-label="Permalink to &quot;常见问题&quot;">​</a></h2><h3 id="导入后没生效" tabindex="-1">导入后没生效 <a class="header-anchor" href="#导入后没生效" aria-label="Permalink to &quot;导入后没生效&quot;">​</a></h3><ol><li><strong>重开游戏了吗</strong> —— 必须完全退出再启动</li><li><strong>码完整吗</strong> —— 聊天软件会截断长文本</li><li><strong>看日志</strong> —— 会记录解析结果</li></ol><h3 id="码太长-聊天软件发不出去" tabindex="-1">码太长，聊天软件发不出去 <a class="header-anchor" href="#码太长-聊天软件发不出去" aria-label="Permalink to &quot;码太长，聊天软件发不出去&quot;">​</a></h3><p>改用<strong>文件方式</strong>：让对方把它存成 <code>.txt</code> 发文件。</p><p>或者更稳的方式：<strong>发布到 <a href="https://atlanticfleet.asia/mods/" target="_blank" rel="noreferrer">Mod 仓库</a></strong>，让朋友从网页复制。</p><h3 id="导入后模型不见了" tabindex="-1">导入后模型不见了 <a class="header-anchor" href="#导入后模型不见了" aria-label="Permalink to &quot;导入后模型不见了&quot;">​</a></h3><p>正常现象 —— 分享码不含模型文件。见上面的说明。</p><h3 id="我能改别人的分享码吗" tabindex="-1">我能改别人的分享码吗 <a class="header-anchor" href="#我能改别人的分享码吗" aria-label="Permalink to &quot;我能改别人的分享码吗&quot;">​</a></h3><p>可以。分享码解出来就是普通的 <code>mod.json</code> 文本，你可以在里面改任何东西（改作者名、改参数）。</p><div class="tip custom-block"><p class="custom-block-title">建议</p><p>如果你<strong>改了别人的 Mod 再分享</strong>，建议在 <code>author</code> 里写明「基于 XXX 修改」，这是基本的礼貌。</p></div><h2 id="相关" tabindex="-1">相关 <a class="header-anchor" href="#相关" aria-label="Permalink to &quot;相关&quot;">​</a></h2><ul><li>在面板上操作 → <a href="/AtlanticFleetSite/docs/use/mods-page">Mod 页：管理已装 Mod</a></li><li>网页在线分享 → <a href="/AtlanticFleetSite/docs/repo/start">Mod 仓库</a></li><li>发布到仓库 → <a href="/AtlanticFleetSite/docs/repo/publish">上传你的 Mod（作者）</a></li></ul>`,40)])])}const b=e(l,[["render",n]]);export{u as __pageData,b as default};
